// ---- protocol (docs/protocol.md "Phase 4") --------------------------------------------------------------------------
constexpr uint16_t kMsgMissionState = 0x0201;  // host -> guests: chapter, checkpoint, objectives, save id, in world
constexpr uint16_t kMsgHostSave = 0x0202;      // host -> guests: the host's newest story checkpoint save file
constexpr uint16_t kMsgCutscene = 0x0203;      // host -> guests: the cutscene that plays on the host ("" = none)
constexpr uint16_t kMsgMissionFail = 0x0205;   // guest -> host: our mission failed (the host decides, FailFlow)
constexpr uint16_t kMsgFailVerdict = 0x0206;   // host -> guests: the host failed / the answer to a guest's failure
constexpr size_t kMaxSave = 200 * 1024;        // our saves are ~40-50 KB; the reliable message limit is 256 KB
constexpr double kScanInterval = 2.0;          // s between looks at the save folder (host)

// The chapter loader we use is the main menu's FREE RIDE (menu::RequestLoad("free_ride")): it loads
// /saves/02_lost_heaven/lh_freeride_extreme.sav, and the bytes of that file are swapped for the save we want
// (StreamInitDetour). So nothing is written anywhere and the menu's own load flow (fade, loading screen) is used.
constexpr const char* kCarrierFile = "02_lost_heaven/lh_freeride_extreme.sav";

// ---- the save swap: game.MainMenu.OpenDebugLoadChapter2 -> OpenDebugLoadChapterString (exe+0x3020350) reads
// /saves/<dir>/<file> into a memory buffer and wraps it in a read stream (exe+0x3c981d0(stream, data, size, 0)) that
// the save system deserialises. At that single call site (pattern below, return address exe+0x30204a1) we hand the
// stream the host's bytes instead (docs/re-notes.md 6). -------------------------------------------------------------
using StreamInitFn = void* (*)(void* stream, const void* data, uint64_t size, uint64_t flags);
constexpr const char* kPatLoadSite =
    "48 8D 4C 24 68 E8 ?? ?? ?? ?? 48 8D 4C 24 68 48 8B D8 E8 ?? ?? ?? ?? 48 8B D0 48 8D 4D A0 45 33 C9 4C 8B C3 E8 ?? ?? "
    "?? ?? 49 8B 8F C8 02 00 00";
constexpr size_t kSiteCallOffset = 0x24;  // the E8 of the stream call inside the pattern
// OpenDebugLoadChapterString(this, C_String* name, bool a, bool b): the menu's loads pass (a, b) = (0, 0) for Free
// Ride / OpenDebugLoadChapter2, (0, 1) for MissionReplay (chapter select: replay mode, the story's quests run) and
// (1, 0) for StartNewGame. When we swap in the host's save the load is turned into a replay-style load (0, 1), else
// the save's quests stay inactive (no mission, no objectives, no cutscene objects).
using ChapterLoadFn = void* (*)(void* self, void* name, uint8_t a, uint8_t b);
constexpr const char* kPatChapterLoad =
    "48 89 5C 24 18 55 56 57 41 54 41 55 41 56 41 57 48 8D 6C 24 F0 48 81 EC 10 01 00 00 4C 8B F9 4C 8B F2 48 8B 89 "
    "C8 02 00 00";
ChapterLoadFn _origChapterLoad = nullptr;
StreamInitFn _origStreamInit = nullptr;
uintptr_t _siteReturn = 0;
std::mutex _swapMu;
std::vector<uint8_t> _swapBytes;  // kept alive until the next swap (the stream reads it during the load)
bool _swapArmed = false;
ULONGLONG _swapArmedAt = 0;  // an armed swap older than a minute is dropped (the load never came)

void* StreamInitDetour(void* stream, const void* data, uint64_t size, uint64_t flags) {
    if (reinterpret_cast<uintptr_t>(_ReturnAddress()) == _siteReturn) {
        std::lock_guard lock(_swapMu);
        if (_swapArmed && GetTickCount64() - _swapArmedAt > 60000) _swapArmed = false;
        if (_swapArmed && !_swapBytes.empty()) {
            _swapArmed = false;
            MC_LOG_INFO("mission: chapter loader: %llu bytes of %s replaced with the save we load (%zu bytes)",
                        static_cast<unsigned long long>(size), kCarrierFile, _swapBytes.size());
            return _origStreamInit(stream, _swapBytes.data(), _swapBytes.size(), flags);
        }
    }
    return _origStreamInit(stream, data, size, flags);
}

void* ChapterLoadDetour(void* self, void* name, uint8_t a, uint8_t b) {
    bool armed;
    {
        std::lock_guard lock(_swapMu);
        armed = _swapArmed && GetTickCount64() - _swapArmedAt <= 60000;
    }
    if (armed) {
        // story_load = replay (default) | story | free: the flags for our loads (tests)
        const std::string mode = core::Config::Get().GetString("story_load", "replay");
        const uint8_t na = mode == "story" ? 1 : 0, nb = mode == "replay" ? 1 : 0;
        MC_LOG_INFO("mission: chapter load (%u, %u) -> (%u, %u) for the swapped save", a, b, na, nb);
        a = na;
        b = nb;
    }
    return _origChapterLoad(self, name, a, b);
}

bool InstallSwap() {
    const uintptr_t site = core::mem::FindPattern(kPatLoadSite);
    if (!site) {
        MC_LOG_WARN("mission: chapter loader call site not found: guests start the host's chapter from its start");
        core::compat::Failed("host checkpoint loading", false);
        return false;
    }
    const uintptr_t call = site + kSiteCallOffset;
    int32_t rel = 0;
    std::memcpy(&rel, reinterpret_cast<const void*>(call + 1), 4);
    void* target = reinterpret_cast<void*>(call + 5 + rel);
    _siteReturn = call + 5;
    if (!core::hook::Install("ChapterLoad_StreamInit", target, &StreamInitDetour, &_origStreamInit)) {
        core::compat::Failed("host checkpoint loading", false);
        return false;
    }
    const uintptr_t load = core::mem::FindPattern(kPatChapterLoad);
    if (!load || !core::hook::Install("ChapterLoad", reinterpret_cast<void*>(load), &ChapterLoadDetour, &_origChapterLoad))
        MC_LOG_WARN("mission: chapter load function not hooked: the host's save loads without its quests");
    MC_LOG_INFO("mission: chapter loader stream at %p (call site return %p)", target,
                reinterpret_cast<void*>(_siteReturn));
    return true;
}

// ---- mission failures: the director's GameOver (docs/re-notes.md 7, "Every mission failure") -------------------------
// The Lua binding game.director:GameOver(reasonId) (exe+0x2245970) reads its string argument, turns it into a number
// (strtoul, base 10) and calls virtual function 1 of the director interface at [G] + 8, G = the global at the
// RIP-relative operand inside the binding (exe+0x635A740 in this build):
//     mov rcx, [G] ; lea rdi, [rcx+8] ; mov rbx, [rdi] ; ... ; mov edx, eax ; mov rcx, rdi ; call [rbx+8]
// Every failure the mission scripts raise ends there: RangeCheckStart's distance check (containers.lua, "you
// abandoned the objective"), timer.lua SimpleFail ("you have failed to make it in time", id 0059310003) and the flow
// node gameOver (game_director/other.lua), which the chapters' fail branches call (mission car lost, target escaped,
// ally died: [likely], only the abandoned objective and the lost car were seen in game). The function itself is
// found at run time (once the director exists) the same way the binding finds it, and hooked: so a C++ caller of it
// is covered too. FailFlow decides whether the game's own answer runs.
constexpr const char* kPatGameOverBinding =
    "40 53 48 83 EC 20 BA 01 00 00 00 48 8B D9 44 8B C2 E8 ?? ?? ?? ?? BA 02 00 00 00 48 8B CB E8 ?? ?? ?? ?? BA 02 00 "
    "00 00 48 8B CB 85 C0 75 2E 44 8D 42 01 E8 ?? ?? ?? ?? BA 04 00 00 00 48 8B CB E8 ?? ?? ?? ?? 4C 8B C0 BA 02 00 00 "
    "00 48 8B CB E8 ?? ?? ?? ?? 33 C0 48 83 C4 20 5B C3 E8 ?? ?? ?? ?? 48 85 C0 74 38 48 8B 0D ?? ?? ?? ?? 48 89 7C 24 "
    "30 48 85 C9 74 06 48 8D 79 08 EB 02 33 FF 48 8B 1F 33 D2 48 8B C8 44 8D 42 0A FF 15 ?? ?? ?? ?? 8B D0 48 8B CF FF "
    "53 08";
constexpr size_t kGameOverGlobalAt = 0x67;  // the "48 8B 0D <disp32>" (mov rcx, [G]) inside the binding
using GameOverFn = uint64_t (*)(void* self, uint32_t reason, void* a3, void* a4);
GameOverFn _origGameOver = nullptr;
uintptr_t _directorGlobal = 0;               // &G
std::atomic<void*> _directorIface{nullptr};  // [G] + 8 when hooked (the only `this` we act on)
bool _gameOverHooked = false, _gameOverGaveUp = false;
double _gameOverTryAt = 0;

// FailFlow and what the hook needs to know (updated every render tick; the hook runs on GameMainThread)
std::mutex _failMu;
FailFlow _fail;
FailRole _failRole = FailRole::None;
bool _failCanReload = false;

double NowS() { return static_cast<double>(GetTickCount64()) / 1000.0; }

std::string ExeCallers() {
    static const uintptr_t exe = reinterpret_cast<uintptr_t>(GetModuleHandleW(nullptr));
    void* frames[8] = {};
    const USHORT n = RtlCaptureStackBackTrace(1, 8, frames, nullptr);
    std::string out;
    char buf[32];
    for (USHORT i = 0; i < n; ++i) {
        const auto a = reinterpret_cast<uintptr_t>(frames[i]);
        if (a < exe || a >= exe + 0x8000000) continue;
        std::snprintf(buf, sizeof buf, " exe+%llx", static_cast<unsigned long long>(a - exe));
        out += buf;
    }
    return out;
}

const char* RoleName(FailRole r) {
    switch (r) {
    case FailRole::HostChapter: return "chapter host";
    case FailRole::HostStory: return "story host";
    case FailRole::Guest: return "guest";
    default: return "not in a co-op story";
    }
}

uint64_t GameOverDetour(void* self, uint32_t reason, void* a3, void* a4) {
    if (self != _directorIface.load()) return _origGameOver(self, reason, a3, a4);  // another class sharing the code
    FailFlow::LocalFailResult r;
    FailRole role;
    std::vector<std::string> lines;
    {
        std::lock_guard lock(_failMu);
        role = _failRole;
        r = _fail.OnLocalFail(role, _failCanReload, reason, NowS());
        lines = _fail.TakeLog();
    }
    MC_LOG_INFO("mission: GameOver(%u) (the mission failed) as %s: %s%s, from%s", reason, RoleName(role),
                r.skipGame ? "the game's own fail flow is skipped" : "the game's own fail flow runs",
                r.fresh ? "" : " (a repeat)", ExeCallers().c_str());
    for (const auto& l : lines) MC_LOG_INFO("mission: %s", l.c_str());
    if (core::trace::IsOpen())
        core::trace::Line("FAIL", "ev=gameover reason=%u role=%u skip=%d fresh=%d", reason, static_cast<unsigned>(role),
                          r.skipGame ? 1 : 0, r.fresh ? 1 : 0);
    if (r.skipGame) return 0;
    return _origGameOver(self, reason, a3, a4);
}

// Install(): where the binding reads the director from.
void FindGameOver() {
    const auto& exe = core::mem::MainModule();
    const uintptr_t binding = core::mem::FindPattern(kPatGameOverBinding);
    if (!binding) {
        _gameOverGaveUp = true;
        MC_LOG_WARN("mission: GameOver binding not found: failed missions take the game's way back (two loads)");
        core::compat::Failed("one-load failed missions", false);
        return;
    }
    _directorGlobal = core::mem::ResolveRip(binding + kGameOverGlobalAt, 3, 7);
    MC_LOG_INFO("mission: GameOver binding at exe+%llx, director global at exe+%llx",
                static_cast<unsigned long long>(binding - exe.base),
                static_cast<unsigned long long>(_directorGlobal - exe.base));
}

// Render thread, every few seconds until done: the director exists once the game runs its scripts.
void TryHookGameOver(double now) {
    if (_gameOverHooked || _gameOverGaveUp || !_directorGlobal || now < _gameOverTryAt) return;
    _gameOverTryAt = now + 5;
    const auto& exe = core::mem::MainModule();
    if (!core::mem::IsReadable(reinterpret_cast<void*>(_directorGlobal), 8)) {
        _gameOverGaveUp = true;
        MC_LOG_WARN("mission: the director global is not readable: failed missions take the game's way back");
        return;
    }
    const uintptr_t director = *reinterpret_cast<const uintptr_t*>(_directorGlobal);
    if (!director) return;  // not created yet
    const uintptr_t iface = director + 8;
    const uintptr_t* vtable = nullptr;
    if (core::mem::IsReadable(reinterpret_cast<void*>(iface), 8))
        vtable = *reinterpret_cast<const uintptr_t* const*>(iface);
    uintptr_t fn = 0;
    if (vtable && core::mem::IsReadable(vtable + 1, 8)) fn = vtable[1];
    if (!fn || !exe.text.Contains(fn)) {
        _gameOverGaveUp = true;
        MC_LOG_WARN("mission: the director's GameOver is not where the binding calls it (vtable %p, function %p): "
                    "failed missions take the game's way back",
                    static_cast<const void*>(vtable), reinterpret_cast<void*>(fn));
        core::compat::Failed("one-load failed missions", false);
        return;
    }
    _directorIface = reinterpret_cast<void*>(iface);
    if (!core::hook::Install("Director_GameOver", reinterpret_cast<void*>(fn), &GameOverDetour, &_origGameOver)) {
        _directorIface = nullptr;
        _gameOverGaveUp = true;
        core::compat::Failed("one-load failed missions", false);
        return;
    }
    _gameOverHooked = true;
    MC_LOG_INFO("mission: the director's GameOver hooked at exe+%llx (director %p, interface vtable exe+%llx)",
                static_cast<unsigned long long>(fn - exe.base), reinterpret_cast<void*>(director),
                static_cast<unsigned long long>(reinterpret_cast<uintptr_t>(vtable) - exe.base));
}

// ---- save ids ---------------------------------------------------------------------------------------------------------
struct Point {
    std::string quest;  // "mm_110_omerta" (the game's quest id: no zero padding)
    std::string cp;     // "cp_020"
    bool operator==(const Point&) const = default;
};

// "checkpoint_mm_010_chase_cp_020" -> {mm_10_chase, cp_020}; anything else -> empty.
Point ParseSaveId(const std::string& id) {
    Point p;
    if (id.rfind("checkpoint_mm_", 0) != 0) return p;
    const size_t cpAt = id.find("_cp_");
    if (cpAt == std::string::npos) return p;
    std::string q = id.substr(11, cpAt - 11);  // mm_010_chase
    size_t i = 3, j = 3;
    while (j < q.size() && q[j] >= '0' && q[j] <= '9') ++j;
    if (j == i) return p;
    p.quest = "mm_" + std::to_string(std::stoi(q.substr(i, j - i))) + q.substr(j);
    p.cp = id.substr(cpAt + 1, 6);  // cp_020
    return p;
}

// The shipped replay save that starts a chapter (edit\saves\00_mission_replay).
std::string ReplayFile(const std::string& quest) {
    static const std::map<std::string, std::string> kOdd = {
        {"mm_30_molotov", "checkpoint_mm_030_molotov_cp_010_cinematic_molotov.sav"},
        {"mm_90_funeral", "mm_090_funeral_init.sav"},
    };
    if (auto it = kOdd.find(quest); it != kOdd.end()) return it->second;
    if (quest.rfind("mm_", 0) != 0) return {};
    size_t j = 3;
    while (j < quest.size() && quest[j] >= '0' && quest[j] <= '9') ++j;
    if (j == 3) return {};
    char num[8];
    std::snprintf(num, sizeof num, "%03d", std::stoi(quest.substr(3, j - 3)));
    return "checkpoint_mm_" + std::string(num) + quest.substr(j) + "_cp_010.sav";
}

// The save id stored in a save file (plain text: "checkpoint_mm_110_omerta_cp_020", "freeroam_game_close", ...).
std::string SaveIdIn(const std::vector<uint8_t>& b) {
    static const char kKey[] = "checkpoint_mm_";
    auto it = std::search(b.begin(), b.end(), kKey, kKey + sizeof kKey - 1);
    if (it == b.end()) return {};
    std::string id;
    for (; it != b.end() && id.size() < 80; ++it) {
        const char c = static_cast<char>(*it);
        if ((c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '_') id += c;
        else break;
    }
    return id;
}

// Where a save puts the player: the position (3 floats, field hash 0x09B305D1) and rotation (quaternion, field hash
// 0x4D1B174C) of the player entity, the last such position block in the file (earlier ones are cars). A load through
// the chapter loader does not use it: the player starts at the Free Ride start (Salieri's bar, -943 -232) whatever the
// save says, and a checkpoint whose own setup does not move him (Omerta cp_020) then started there, away from the
// mission area and its checks (docs/re-notes.md 7). So the story sync puts him there itself (Lua MS.Activate).
struct Spot {
    bool valid = false;
    float x = 0, y = 0, z = 0, dx = 0, dy = 1;
};

Spot SaveSpotIn(const std::vector<uint8_t>& b) {
    static const uint8_t kPos[] = {0x04, 0, 0, 0, 0xD1, 0x05, 0xB3, 0x09, 0x0C, 0, 0, 0};
    static const uint8_t kRot[] = {0x4C, 0x17, 0x1B, 0x4D, 0x10, 0, 0, 0};
    Spot s;
    const auto it = std::find_end(b.begin(), b.end(), std::begin(kPos), std::end(kPos));
    if (it == b.end() || b.end() - it < static_cast<ptrdiff_t>(sizeof kPos + 12)) return s;
    const size_t at = static_cast<size_t>(it - b.begin()) + sizeof kPos;
    float v[3];
    std::memcpy(v, b.data() + at, sizeof v);
    for (float f : v)
        if (!(f > -5000.f && f < 5000.f)) return s;  // also rejects NaN
    s.valid = true;
    s.x = v[0];
    s.y = v[1];
    s.z = v[2];
    // heading from the rotation about z: forward (0, 1) turned by yaw = 2 atan2(qz, qw)
    const auto from = b.begin() + static_cast<ptrdiff_t>(at + 12);
    const auto to = b.begin() + static_cast<ptrdiff_t>(std::min(b.size(), at + 12 + 80));
    const auto r = std::search(from, to, std::begin(kRot), std::end(kRot));
    if (r != to && b.end() - r >= static_cast<ptrdiff_t>(sizeof kRot + 16)) {
        float q[4];
        std::memcpy(q, b.data() + (r - b.begin()) + sizeof kRot, sizeof q);
        const float yaw = 2.f * std::atan2(q[2], q[3]);
        if (yaw == yaw) {
            s.dx = -std::sin(yaw);
            s.dy = std::cos(yaw);
        }
    }
    return s;
}

// ---- the host's save folder -------------------------------------------------------------------------------------------
std::filesystem::path SaveRoot() {
    PWSTR docs = nullptr;
    std::filesystem::path p;
    if (SUCCEEDED(SHGetKnownFolderPath(FOLDERID_Documents, 0, nullptr, &docs)) && docs)
        p = std::filesystem::path(docs) / L"My Games" / L"Mafia Definitive Edition" / L"Data";
    CoTaskMemFree(docs);
    return p;
}

struct SaveFile {
    std::filesystem::path path;
    uint64_t stamp = 0;  // last write time
    uint64_t size = 0;
    std::string id;      // save id in it ("" = not a story checkpoint)
};

